// Simple Canvas Escape game
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = canvas.clientWidth || 800;
canvas.height = canvas.clientHeight || 600;

// Player ship
const ship = {
  x: canvas.width / 2,
  y: canvas.height - 50,
  radius: 12,
  speed: 4,
  color: 'lime',
};

let keys = {};
window.addEventListener('keydown', e => { keys[e.key] = true; });
window.addEventListener('keyup', e => { keys[e.key] = false; });

// Asteroids & fuel
const asteroids = [];
const fuels = [];
let asteroidTimer = 0;
let fuelTimer = 0;
let score = 0;
let fuel = 100; // seconds
let gameOver = false;

function spawnAsteroid() {
  const size = Math.random() * 30 + 20;
  asteroids.push({
    x: Math.random() * (canvas.width - size) + size / 2,
    y: -size,
    radius: size / 2,
    speed: Math.random() * 2 + 1,
  });
}

function spawnFuel() {
  const size = 10;
  fuels.push({
    x: Math.random() * (canvas.width - size) + size / 2,
    y: -size,
    radius: size / 2,
    speed: 1.5,
  });
}

function update(dt) {
  if (gameOver) return;
  // Player movement
  if (keys.ArrowLeft && ship.x - ship.radius > 0) ship.x -= ship.speed;
  if (keys.ArrowRight && ship.x + ship.radius < canvas.width) ship.x += ship.speed;
  if (keys.ArrowUp && ship.y - ship.radius > 0) ship.y -= ship.speed;
  if (keys.ArrowDown && ship.y + ship.radius < canvas.height) ship.y += ship.speed;

  // Spawn asteroids/fuel
  asteroidTimer += dt;
  fuelTimer += dt;
  if (asteroidTimer > 1000) { // every second
    spawnAsteroid();
    asteroidTimer = 0;
  }
  if (fuelTimer > 3000) { // every 3 seconds
    spawnFuel();
    fuelTimer = 0;
  }

  // Update asteroids
  asteroids.forEach((a, i) => {
    a.y += a.speed;
    if (a.y - a.radius > canvas.height) asteroids.splice(i, 1);
    // collision with ship
    const dx = a.x - ship.x;
    const dy = a.y - ship.y;
    const dist = Math.hypot(dx, dy);
    if (dist < a.radius + ship.radius) gameOver = true;
  });

  // Update fuels
  fuels.forEach((f, i) => {
    f.y += f.speed;
    if (f.y - f.radius > canvas.height) fuels.splice(i, 1);
    const dx = f.x - ship.x;
    const dy = f.y - ship.y;
    const dist = Math.hypot(dx, dy);
    if (dist < f.radius + ship.radius) {
      fuel += 20; // add fuel seconds
      fuels.splice(i, 1);
    }
  });

  // Decrease fuel over time
  fuel -= dt / 1000;
  if (fuel <= 0) gameOver = true;
  score += dt / 1000;
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Ship
  ctx.fillStyle = ship.color;
  ctx.beginPath();
  ctx.arc(ship.x, ship.y, ship.radius, 0, Math.PI * 2);
  ctx.fill();

  // Asteroids
  ctx.fillStyle = 'gray';
  asteroids.forEach(a => {
    ctx.beginPath();
    ctx.arc(a.x, a.y, a.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  // Fuel cells
  ctx.fillStyle = 'gold';
  fuels.forEach(f => {
    ctx.beginPath();
    ctx.arc(f.x, f.y, f.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  // HUD
  ctx.fillStyle = 'white';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Score: ${Math.floor(score)}`, 10, 20);
  ctx.fillText(`Fuel: ${Math.max(0, Math.floor(fuel))}`, 10, 40);

  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '48px sans-serif';
    ctx.fillText('Game Over', canvas.width / 2 - 120, canvas.height / 2);
  }
}

let last = 0;
function loop(timestamp) {
  const dt = timestamp - last;
  last = timestamp;
  update(dt);
  draw();
  if (!gameOver) requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
